import React,{useEffect,useMemo,useState} from 'react';
import {useWebAdminAuth} from './AdminRuntime';
import {createG263NativeAdminReader} from './g263-native-admin-trace-reader.mjs';
import type {NativeG263Kind,NativeG263Evidence}
 from './g263-native-admin-trace-reader.mjs';

/**
 * Real PG17 Admin evidence is intentionally separated from the legacy priced
 * CI receipt panel. No LIVE, no settlement, no fictitious drivers, no IDs
 * generated by this browser. AAL2 and G27 remain server authorities.
 */
const KINDS:NativeG263Kind[]=[
 'AUTO_RIDE','MOTO_RIDE','DELIVERY_AUTO','DELIVERY_MOTO','COMMERCE'
];
const UUID=/^[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}$/;
const host='https://qore-mobile-backend-staging-staging.up.railway.app';
export function NativeAdminTracePanel({
 authorized,subject
}:{authorized:boolean;subject:string|null}){
 const auth=useWebAdminAuth();
 const [kind,setKind]=useState<NativeG263Kind>('AUTO_RIDE');
 const [id,setId]=useState('');
 const [item,setItem]=useState<NativeG263Evidence|null>(null);
 const [viewer,setViewer]=useState<string|null>(null);
 const [error,setError]=useState('');
 const [busy,setBusy]=useState(false);
 const [clock,setClock]=useState(Date.now());
 const reader=useMemo(()=>createG263NativeAdminReader({
  enabled:import.meta.env.VITE_G263_NATIVE_TRACE_ENABLED==='true',
  ownerApproved:import.meta.env.VITE_G263_OWNER_APPROVED==='true',
  externalHttpsVerified:import.meta.env.VITE_G263_EXTERNAL_HTTPS_VERIFIED==='true',
  nativePgVerified:import.meta.env.VITE_G263_NATIVE_PG_VERIFIED==='true',
  aal2ServerVerified:import.meta.env.VITE_G263_ADMIN_AAL2_VERIFIED==='true',
  origin:import.meta.env.VITE_G263_STAGING_ORIGIN,
  getSession:()=>auth?.readSession()??Promise.resolve(null),
  fetchImpl:(url,opts)=>fetch(url,opts)
 }),[auth]);
 useEffect(()=>{
  const timer=setInterval(()=>setClock(Date.now()),5000);
  return ()=>clearInterval(timer);
 },[]);
 useEffect(()=>{
  reader.cancelPending();
  setItem(null);setError('');setViewer(null);setBusy(false);
  return ()=>reader.cancelPending();
 },[reader,authorized,subject]);
 const ready=authorized&&reader.isConfigured()&&subject!==null;
 const visible=item!==null&&viewer===subject&&authorized&&clock<item.expiresAt
  &&item.serviceKind===kind&&item.serviceId===id?item:null;
 const reset=()=>{
  reader.cancelPending();setItem(null);setViewer(null);setError('');setBusy(false);
 };
 const inspect=async()=>{
  if(!ready||!UUID.test(id)||busy)return;
  const identity=subject;
  setBusy(true);setError('');setItem(null);setViewer(null);
  const result=await reader.read(kind,id);
  if(result.ok){
   const latest=await auth?.readSession().catch(()=>null);
   if(latest?.subject===identity&&latest?.role==='admin'&&latest.mfaVerified){
    setItem(result.data);setViewer(identity);
   }else setError('La sesión Admin cambió; lectura descartada.');
  }else setError('Lectura rechazada: '+result.code);
  setBusy(false);setClock(Date.now());
 };
 return <section className="panel detail">
  <div className="section-head"><div>
   <h2>Registros originales de PostgreSQL · G262</h2>
   <p>Consulta alternativa por ID real de las cinco modalidades. Muestra únicamente
    estado, revisiones y eventos del servidor; no certifica tarifas ni liquidaciones.</p>
  </div><span className="muted-tag">STAGING · SOLO LECTURA</span></div>
  {!ready&&<p role="status">La consulta externa permanece bloqueada hasta
   comprobar despliegue HTTPS, identidad Admin AAL2 y autorización independiente.</p>}
  <label htmlFor="g263-kind">Modalidad</label>
  <select id="g263-kind" value={kind} disabled={busy}
   onChange={e=>{reset();setKind(e.target.value as NativeG263Kind);}}>
   {KINDS.map(k=><option key={k} value={k}>{k}</option>)}
  </select>
  <label htmlFor="g263-id">ID original del servidor</label>
  <input id="g263-id" value={id} placeholder="UUID del viaje, envío o pedido"
   autoComplete="off" maxLength={36} disabled={busy||!ready}
   onChange={e=>{reset();setId(e.target.value.trim());}}/>
  <div className="refresh-actions">
   <button type="button" disabled={!ready||!UUID.test(id)||busy}
    onClick={()=>{void inspect();}}>{busy?'Consultando…':'Consultar registro original'}</button>
   <button type="button" disabled={busy&&!item} onClick={reset}>Limpiar</button>
  </div>
  {error&&ready&&<p role="alert">{error}</p>}
  {visible&&<div className="zone-rows">
   <div className="zone-row"><div>
    <strong>{visible.serviceKind} · {visible.serviceId}</strong>
    <small>Estado: {visible.status} · revisión {visible.revision}</small>
    <small>Solicitud original: {visible.requestKey}</small>
    <small>Eventos verificados: {visible.events.length} de {visible.totalEvents}
     {visible.eventsTruncated?' (historial parcial)':''}</small>
    {visible.events.map(e=><small key={e.eventId}>
     Revisión {e.revision}: {e.status}</small>)}
    <small>Conciliación financiera: NO CERTIFICADA</small>
    <small>Ejecución E2E externa: NO CERTIFICADA</small>
   </div><div className="zone-count">QA<small>Sin producción</small></div></div>
  </div>}
  <p className="training-disclaimer">Un registro persistido no es evidencia de
   pagos, GPS, identidad documental ni habilitación comercial. El servidor
   vuelve a verificar AAL2, revocación de sesión y rol Admin exclusivo.</p>
 </section>;
}
